<script setup>
import {computed, onMounted, ref} from 'vue'
import {api} from '../lib/api.js'
import PageHeader from '../components/PageHeader.vue'
const rows=ref([]),topTalkers=ref([]),arp=ref([]),nodes=ref([]),nodeId=ref(''),external=ref(''),page=ref(1),pageSize=ref(100),pages=ref(1),total=ref(0),loading=ref(false),error=ref(''),message=ref('')
const selectedNode=computed(()=>nodes.value.find(node=>node.id===nodeId.value))
async function load(){loading.value=true;error.value='';try{const query=new URLSearchParams({page:page.value,pageSize:pageSize.value});if(nodeId.value)query.set('nodeId',nodeId.value);if(external.value)query.set('external',external.value);const result=await api(`/mapping?${query}`);rows.value=result.rows;topTalkers.value=result.topTalkers;pages.value=result.pages;total.value=result.total;const arpResult=await api(`/mapping/arp${nodeId.value?`?nodeId=${encodeURIComponent(nodeId.value)}`:''}`);arp.value=arpResult.items}catch(e){error.value=e.message}finally{loading.value=false}}
async function collectArp(){if(!nodeId.value)return;message.value='';try{await api(`/nodes/${nodeId.value}/arp/collect`,{method:'POST'});message.value='ARP collection queued. Refresh in a moment.'}catch(e){error.value=e.message}}
async function rebuild(){message.value='';try{const result=await api('/mapping/rebuild',{method:'POST'});message.value=`Rebuilt ${result.rows} mapping pair${result.rows===1?'':'s'} from ${result.events} events.`;await load()}catch(e){error.value=e.message}}
function next(delta){page.value=Math.min(pages.value,Math.max(1,page.value+delta));load()}
onMounted(async()=>{nodes.value=await api('/nodes');await load()})
</script>
<template><div class="view mapping-view"><PageHeader eyebrow="VISIBILITY / NETWORK MAP" title="Network mapping" description="Correlate observed traffic into internal node pairs, external connections and top talkers"><div class="page-actions"><button class="button secondary" @click="rebuild"><i class="mdi mdi-database-refresh-outline"></i> Rebuild map</button><button class="button primary" @click="load"><i class="mdi mdi-refresh"></i> Refresh</button></div></PageHeader><div v-if="error" class="error-msg">{{error}}</div><div v-if="message" class="success-msg">{{message}}</div><div class="metric-grid"><div class="metric glass"><div class="metric-top"><span>MAPPED PAIRS</span><i class="mdi mdi-vector-link"></i></div><strong>{{total}}</strong><small>Observed connection patterns</small></div><div class="metric glass"><div class="metric-top"><span>TOP TALKER</span><i class="mdi mdi-swap-vertical"></i></div><strong>{{topTalkers[0]?.hostname||'—'}}</strong><small>{{topTalkers[0]?.connections||0}} connections</small></div><div class="metric glass"><div class="metric-top"><span>ARP ENTRIES</span><i class="mdi mdi-lan-connect"></i></div><strong>{{arp.length}}</strong><small>{{selectedNode?.hostname||'All managed nodes'}}</small></div><div class="metric glass"><div class="metric-top"><span>PAGE</span><i class="mdi mdi-table-large"></i></div><strong>{{page}}<span>/{{pages}}</span></strong><small>Rows {{pageSize}} per page</small></div></div><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">CONNECTION GRAPH</span><h2>Node pairs and external traffic</h2></div><div class="table-tools"><select v-model="nodeId" aria-label="Filter by node" @change="page=1;load()"><option value="">All nodes</option><option v-for="node in nodes" :key="node.id" :value="node.id">{{node.hostname}}</option></select><select v-model="external" aria-label="Filter traffic scope" @change="page=1;load()"><option value="">Internal and external</option><option value="0">Internal only</option><option value="1">External only</option></select></div></div><div class="table-wrap"><table><thead><tr><th>SOURCE</th><th>DESTINATION</th><th>SCOPE</th><th>PROTOCOL</th><th>PORT</th><th>CONNECTIONS</th><th>LAST SEEN</th></tr></thead><tbody><tr v-for="row in rows" :key="row.map_key"><td><strong>{{row.source_hostname||row.source_ip}}</strong><small class="mono">{{row.source_ip}}</small></td><td><strong>{{row.destination_hostname||row.destination_ip}}</strong><small class="mono">{{row.destination_ip}}</small></td><td><span class="status" :class="row.external?'pending':'reachable'">{{row.external?'External':'Internal'}}</span></td><td>{{row.protocol}}</td><td class="mono">{{row.destination_port||'—'}}</td><td><strong>{{row.connection_count}}</strong></td><td>{{row.last_seen_at?new Date(row.last_seen_at).toLocaleString():'—'}}</td></tr><tr v-if="!rows.length"><td colspan="7" class="empty-table">{{loading?'Loading network observations…':'No mapped traffic yet. Collect firewall events or rebuild the map.'}}</td></tr></tbody></table></div><div class="pagination"><span>{{total}} pair{{total===1?'':'s'}}</span><button class="button small secondary" :disabled="page<=1" @click="next(-1)">Previous</button><button class="button small secondary" :disabled="page>=pages" @click="next(1)">Next</button></div></section><div class="dashboard-grid"><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">TOP TALKERS</span><h2>Most active nodes</h2></div></div><div class="table-wrap"><table><thead><tr><th>NODE</th><th>CONNECTIONS</th></tr></thead><tbody><tr v-for="talker in topTalkers" :key="`${talker.node_id||talker.hostname}`"><td><strong>{{talker.hostname||'External peer'}}</strong></td><td>{{talker.connections}}</td></tr><tr v-if="!topTalkers.length"><td colspan="2" class="empty-table">No talkers yet.</td></tr></tbody></table></div></section><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">ARP SNAPSHOT</span><h2>Neighbor table</h2></div><button class="button small secondary" :disabled="!nodeId" @click="collectArp"><i class="mdi mdi-download-network"></i> Collect from node</button></div><div class="table-wrap"><table><thead><tr><th>NODE</th><th>IP</th><th>MAC</th><th>INTERFACE</th><th>STATE</th></tr></thead><tbody><tr v-for="entry in arp.slice(0,100)" :key="entry.id"><td>{{entry.hostname}}</td><td class="mono">{{entry.ip}}</td><td class="mono">{{entry.mac||'—'}}</td><td>{{entry.interface||'—'}}</td><td>{{entry.state||'—'}}</td></tr><tr v-if="!arp.length"><td colspan="5" class="empty-table">No ARP observations yet.</td></tr></tbody></table></div></section></div></div></template>
<style scoped>.pagination{display:flex;justify-content:flex-end;align-items:center;gap:8px;padding:14px 16px;color:var(--muted);font-size:.72rem}.pagination span{margin-right:auto}.mapping-view small{display:block;color:var(--muted);margin-top:3px}.mapping-view .metric strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%}</style>
